#include <algorithm>

class Solution {
private:
    long long getSum(long long num, int x) {
        ++num;
        long long res = 0;
        for (int i = 1; i <= 62; ++i) {
            if (i % x == 0) {
                long long group = 1ULL << i;
                long long half = 1ULL << (i - 1);
                res += (num / group) * half;
                res += std::max(0LL, (num % group) - half);
            }
        }
        return res;
    }
public:
    long long findMaximumNumber(long long k, int x) {
        long long l = 1, r = 1e15;
        while (l < r) {
            long long m = (l + r + 1) / 2;
            if (getSum(m, x) <= k) {
                l = m;
            } else {
                r = m - 1;
            }
        }
        return l;
    }
};

class Solution {
    private long getSum(long num, int x) {
        num++;
        long res = 0;
        for (int i = 1; i <= 62; i++) {
            if (i % x == 0) {
                long group = 1L << i;
                long half = 1L << (i - 1);
                res += (num / group) * half;
                res += Math.max(0L, (num % group) - half);
            }
        }
        return res;
    }

    public long findMaximumNumber(long k, int x) {
        long l = 1, r = (long) 1e15;
        while (l < r) {
            long m = (l + r + 1) / 2;
            if (getSum(m, x) <= k) {
                l = m;
            } else {
                r = m - 1;
            }
        }
        return l;
    }
}

var findMaximumNumber = function(k, x) {
    const bigK = BigInt(k);
    const bigX = BigInt(x);
    function getSum(num) {
        num = num + 1n;
        let res = 0n;
        for (let i = 1n; i <= 62n; i++) {
            if (i % bigX === 0n) {
                const group = 1n << i;
                const half = 1n << (i - 1n);
                res += (num / group) * half;
                const rem = num % group;
                if (rem > half) {
                    res += rem - half;
                }
            }
        }
        return res;
    }
    let l = 1n, r = 1000000000000000n;
    while (l < r) {
        const m = (l + r + 1n) / 2n;
        if (getSum(m) <= bigK) {
            l = m;
        } else {
            r = m - 1n;
        }
    }
    return Number(l);
};
